#include <unordered_map>
#include <vector>
using namespace std;
int subarraySum(vector<int>&a, int k) {
    unordered_map<int, int>m;
    m[0]=1;
    int cnt=0, ps=0;
    for (int x:a) {
        ps+=x;
        cnt+=m.count(ps-k)?m[ps-k]:0;
        m[ps]++;
    }
    return cnt;
}
